'use client';
import { useEffect, useId, useMemo, useRef, useState, type ReactNode } from 'react';
import { duration as D, easing, useStudioMotion } from '../../../motion';
import {
  BARS, BASE_PRICE, DEFAULT_BUILD, EXTRAS, FENDER_MAX_TYRE, FRAMES, MODEL, PAINTS, SIZES, TYRES,
  barOf, codeOf, countBuilds, fendersFit, fitOf, formatDelta, formatPrice, frameOf, fromHash, interpolateFit, mm,
  paintOf, priceOf, sameBuild, sizeOf, solve, toHash, tyreOf,
  type Build, type ExtraId, type Fit, type TyreId,
} from './bike';
import { BarIcon, BikeDrawing, describeBuild } from './Drawing';
import { Ticker } from './Ticker';
import styles from './styles.module.css';

/** cubic-bezier evaluator so the geometry tween uses the same `emphasized` token as the CSS. */
function bezier([x1, y1, x2, y2]: readonly [number, number, number, number]) {
  const cx = 3 * x1, bx = 3 * (x2 - x1) - cx, ax = 1 - cx - bx;
  const cy = 3 * y1, by = 3 * (y2 - y1) - cy, ay = 1 - cy - by;
  const sx = (t: number) => ((ax * t + bx) * t + cx) * t;
  const dx = (t: number) => (3 * ax * t + 2 * bx) * t + cx;
  return (x: number): number => {
    if (x <= 0) return 0;
    if (x >= 1) return 1;
    let t = x;
    for (let i = 0; i < 8; i++) { const e = sx(t) - x; const d = dx(t); if (Math.abs(e) < 1e-5 || Math.abs(d) < 1e-6) break; t -= e / d; }
    t = Math.min(1, Math.max(0, t));
    return ((ay * t + by) * t + cy) * t;
  };
}
const EMPHASIZED = bezier(easing.emphasized);

/** Tween the geometry numbers (size and tyre width) so the frame visibly grows or shrinks. Interruptible. */
function useTweenedFit(target: Fit, reduced: boolean): Fit {
  const [fit, setFit] = useState(target);
  const current = useRef(target);
  useEffect(() => {
    const from = current.current;
    if (reduced) { current.current = target; setFit(target); return; }
    let raf = 0;
    const start = performance.now();
    const tick = (now: number) => {
      const t = Math.min(1, (now - start) / D.moderate);
      const v = interpolateFit(from, target, EMPHASIZED(t));
      current.current = v;
      setFit(v);
      if (t < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [target, reduced]);
  return fit;
}

interface Opt { id: string; name: string; note: string; price: number }

function Choices<T extends Opt>({ n, legend, hint, name, options, value, onPick, kind, children, render }: {
  n: string; legend: string; hint?: ReactNode; name: string; options: readonly T[]; value: string; kind: string;
  onPick: (o: T) => void; render: (o: T) => ReactNode; children?: ReactNode;
}) {
  const uid = useId();
  return (
    <fieldset className={styles.group} aria-describedby={hint ? `${uid}h` : undefined}>
      <legend className={styles.legend}><span className={styles.num} aria-hidden="true">{n}</span>{legend}</legend>
      {hint ? <p id={`${uid}h`} className={styles.hint}>{hint}</p> : null}
      <div className={styles.choices} data-kind={kind}>
        {options.map((o) => (
          <label key={o.id} className={styles.choice}>
            <input className={styles.input} type="radio" name={name} value={o.id} checked={value === o.id} onChange={() => onPick(o)} />
            {render(o)}
            <span className={styles.delta}>{formatDelta(o.price)}</span>
          </label>
        ))}
      </div>
      {children}
    </fieldset>
  );
}

export default function ProductConfigurator() {
  const uid = useId();
  const { reduced } = useStudioMotion();
  const [build, setBuild] = useState<Build>(DEFAULT_BUILD);
  const [ready, setReady] = useState(false);
  const [status, setStatus] = useState('');
  const [notice, setNotice] = useState<{ text: string; undo: Build } | null>(null);
  const [requested, setRequested] = useState(false);
  const [copied, setCopied] = useState<'idle' | 'copied' | 'manual'>('idle');
  const linkField = useRef<HTMLInputElement>(null);
  const ticketHeading = useRef<HTMLHeadingElement>(null);

  // Shareable state: the build lives in the URL hash (replaceState, so Back still leaves the page).
  useEffect(() => {
    const read = () => { const b = fromHash(window.location.hash); if (b) setBuild((cur) => (sameBuild(cur, b) ? cur : b)); };
    read();
    setReady(true);
    window.addEventListener('hashchange', read);
    return () => window.removeEventListener('hashchange', read);
  }, []);
  useEffect(() => {
    if (!ready) return;
    const h = toHash(build);
    if (window.location.hash !== h) window.history.replaceState(window.history.state, '', h);
  }, [build, ready]);

  const target = useMemo(() => fitOf(build), [build.size, build.tyre]); // eslint-disable-line react-hooks/exhaustive-deps
  const fit = useTweenedFit(target, reduced);
  const combos = useMemo(countBuilds, []);

  const size = sizeOf(build), frame = frameOf(build), paint = paintOf(build), bar = barOf(build), tyre = tyreOf(build);
  const total = priceOf(build);
  const code = codeOf(build);
  const geo = solve(target);

  const commit = (next: Build, said: string) => {
    setBuild(next);
    setRequested(false);
    setCopied('idle');
    setStatus(`${said} Total ${formatPrice(priceOf(next))}.`);
  };

  const pickTyre = (id: TyreId) => {
    const t = TYRES.find((x) => x.id === id) ?? TYRES[0];
    if (!fendersFit(id) && build.extras.includes('fenders')) {
      setNotice({ text: `Fenders removed: the blades clear tyres up to ${FENDER_MAX_TYRE} mm.`, undo: build });
      commit({ ...build, tyre: id, extras: build.extras.filter((e) => e !== 'fenders') }, `Tyres: ${t.name}. Fenders removed, they clear tyres up to ${FENDER_MAX_TYRE} mm.`);
    } else {
      setNotice(null);
      commit({ ...build, tyre: id }, `Tyres: ${t.name}.`);
    }
  };

  const toggleExtra = (id: ExtraId, on: boolean) => {
    if (id === 'fenders' && on && !fendersFit(build.tyre)) return;
    const e = EXTRAS.find((x) => x.id === id) ?? EXTRAS[0];
    setNotice(null);
    const extras = EXTRAS.map((x) => x.id).filter((x) => (x === id ? on : build.extras.includes(x)));
    commit({ ...build, extras }, `${e.name} ${on ? 'added' : 'removed'}.`);
  };

  const undo = () => {
    if (!notice) return;
    const prev = notice.undo;
    setNotice(null);
    commit(prev, `Restored ${tyreOf(prev).name} tyres with fenders.`);
  };

  const reset = () => { setNotice(null); commit(DEFAULT_BUILD, 'Reset to the standard build.'); };

  const copyLink = async () => {
    const url = window.location.href;
    try {
      await navigator.clipboard.writeText(url);
      setCopied('copied');
    } catch {
      setCopied('manual');
      requestAnimationFrame(() => { linkField.current?.focus(); linkField.current?.select(); });
    }
  };

  const fendersBlocked = !fendersFit(build.tyre);
  const lines: { k: string; label: string; value: string; price: number | null }[] = [
    { k: 'base', label: 'Frameset & build', value: `${MODEL}, size ${size.name}`, price: BASE_PRICE },
    { k: 'frame', label: 'Frame', value: frame.name, price: frame.price },
    { k: 'paint', label: 'Paint', value: frame.id === 'titanium' ? `${paint.name}, fork only` : paint.name, price: paint.price },
    { k: 'bar', label: 'Handlebar', value: bar.name, price: bar.price },
    { k: 'tyre', label: 'Tyres', value: tyre.name, price: tyre.price },
    ...EXTRAS.filter((e) => build.extras.includes(e.id)).map((e) => ({ k: e.id, label: 'Extra', value: e.name, price: e.price })),
  ];

  return (
    <div className={styles.root} data-reduced={reduced || undefined}>
      <div className={styles.layout}>
        <header className={styles.intro}>
          <p className={styles.brand}><span className={styles.wordmark}>Hollin Cycles</span><span className={styles.tag}>Sample pricing</span></p>
          <h2 className={styles.model}>{MODEL}</h2>
          <p className={styles.lede}>A steel all-road tourer, built to order. Pick a size and parts; the drawing is recalculated from the frame geometry as you choose.</p>
        </header>

        <section className={styles.plate} aria-labelledby={`${uid}plate`}>
          <div className={styles.plateHead}>
            <h3 id={`${uid}plate`} className={styles.plateTitle}>Side elevation, drive side</h3>
            <span className={styles.code} aria-label={`Build code ${code}`}>{code}</span>
          </div>
          <div className={styles.drawingWrap}>
            <BikeDrawing build={build} fit={fit} uid={uid} />
          </div>
          <p className={styles.caption}>{describeBuild(build)}</p>
          <div className={styles.strip}>
            <p className={styles.total}>
              <span className={styles.totalLabel}>Total</span>
              <Ticker value={total} format={formatPrice} reduced={reduced} className={styles.totalValue} />
            </p>
            <button type="button" className={styles.primary} onClick={() => { setRequested(true); ticketHeading.current?.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth', block: 'start' }); }}>
              Request this build
            </button>
          </div>
        </section>

        <form className={styles.options} aria-label="Build options" onSubmit={(e) => e.preventDefault()}>
          <Choices n="01" legend="Frame size" name={`${uid}size`} kind="size" options={SIZES} value={build.size}
            hint="Sizes are the seat tube length in centimetres; under each is a rider height range in centimetres. Heights are a starting point: stack and reach below are what to compare."
            onPick={(o) => commit({ ...build, size: o.id }, `Size ${o.name}.`)}
            render={(o) => (<><span className={styles.sizeNum}>{o.name}</span><span className={styles.note}>{o.rider}<span className={styles.srOnly}> cm rider height</span></span></>)}>
            <dl className={styles.geo} aria-label={`Geometry for size ${size.name}, in millimetres and degrees`}>
              <div><dt>Stack</dt><dd>{mm(size.stack)}</dd></div>
              <div><dt>Reach</dt><dd>{mm(size.reach)}</dd></div>
              <div><dt>Wheelbase</dt><dd>{mm(geo.wheelbase)}</dd></div>
              <div><dt>Head angle</dt><dd>{size.hta}°</dd></div>
              <div><dt>Seat angle</dt><dd>{size.sta}°</dd></div>
            </dl>
          </Choices>

          <Choices n="02" legend="Frame" name={`${uid}frame`} kind="frame" options={FRAMES} value={build.frame}
            onPick={(o) => commit({ ...build, frame: o.id }, `Frame: ${o.name}.`)}
            render={(o) => (<><span className={styles.name}>{o.name}</span><span className={styles.note}>{o.note}</span></>)} />

          <Choices n="03" legend="Paint" name={`${uid}paint`} kind="paint" options={PAINTS} value={build.paint}
            hint={frame.id === 'titanium' ? 'Titanium frames stay raw, so your colour goes on the steel fork.' : undefined}
            onPick={(o) => commit({ ...build, paint: o.id }, `Paint: ${o.name}${frame.id === 'titanium' ? ', on the fork' : ''}.`)}
            render={(o) => (
              <span className={styles.paintRow}>
                <span className={styles.swatch} style={{ background: o.colour }} aria-hidden="true" />
                <span className={styles.paintText}><span className={styles.name}>{o.name}</span><span className={styles.note}>{o.note}</span></span>
              </span>
            )} />

          <Choices n="04" legend="Handlebar" name={`${uid}bar`} kind="bar" options={BARS} value={build.bar}
            onPick={(o) => commit({ ...build, bar: o.id }, `Handlebar: ${o.name}.`)}
            render={(o) => (<><BarIcon id={o.id} /><span className={styles.name}>{o.name}</span><span className={styles.note}>{o.note}</span></>)} />

          <Choices n="05" legend="Tyres" name={`${uid}tyre`} kind="tyre" options={TYRES} value={build.tyre}
            onPick={(o) => pickTyre(o.id)}
            render={(o) => (<><span className={styles.name}>{o.name}</span><span className={styles.note}>{o.note}</span></>)}>
            {notice ? (
              <p className={styles.notice}>
                <span>{notice.text}</span>
                <button type="button" className={styles.textBtn} onClick={undo}>Undo</button>
              </p>
            ) : null}
          </Choices>

          <fieldset className={styles.group}>
            <legend className={styles.legend}><span className={styles.num} aria-hidden="true">06</span>Fitted extras</legend>
            <div className={styles.extras}>
              {EXTRAS.map((e) => {
                const blocked = e.id === 'fenders' && fendersBlocked;
                const on = build.extras.includes(e.id);
                return (
                  <div key={e.id} className={styles.extraItem}>
                    <label className={styles.extra} data-blocked={blocked || undefined}>
                      <input className={styles.input} type="checkbox" checked={on} aria-disabled={blocked || undefined}
                        aria-describedby={blocked ? `${uid}fend` : undefined}
                        onChange={(ev) => toggleExtra(e.id, ev.currentTarget.checked)} />
                      <span className={styles.box} aria-hidden="true">
                        <svg viewBox="0 0 16 16"><path d="m3.5 8.5 3 3 6-6.5" /></svg>
                      </span>
                      <span className={styles.extraText}><span className={styles.name}>{e.name}</span><span className={styles.note}>{e.note}</span></span>
                      <span className={styles.delta}>{formatDelta(e.price)}</span>
                    </label>
                    {blocked ? (
                      <p id={`${uid}fend`} className={styles.blockedNote}>
                        <span>Fenders clear tyres up to {FENDER_MAX_TYRE} mm, so they can’t go on 45 mm gravel tyres.</span>
                        <button type="button" className={styles.textBtn} onClick={() => commit({ ...build, tyre: 'road38', extras: EXTRAS.map((x) => x.id).filter((x) => x === 'fenders' || build.extras.includes(x)) }, 'Tyres: 38 mm all-road. Full-length fenders added.')}>
                          Switch to 38 mm tyres and add fenders
                        </button>
                      </p>
                    ) : null}
                  </div>
                );
              })}
            </div>
          </fieldset>

          <section className={styles.ticket} aria-labelledby={`${uid}ticket`}>
            <div className={styles.ticketHead}>
              <h3 id={`${uid}ticket`} ref={ticketHeading} tabIndex={-1} className={styles.ticketTitle}>Your build</h3>
              <span className={styles.code}>{code}</span>
            </div>
            <dl className={styles.lines}>
              {lines.map((l) => (
                <div key={l.k} className={styles.line}>
                  <dt>{l.label}</dt>
                  <dd>{l.value}</dd>
                  <dd className={styles.linePrice}>{l.k === 'base' ? formatPrice(l.price ?? 0) : formatDelta(l.price ?? 0)}</dd>
                </div>
              ))}
            </dl>
            <p className={styles.ticketTotal}><span>Total</span><span className={styles.ticketSum}>{formatPrice(total)}</span></p>
            <p className={styles.terms}>Sample pricing in US dollars before sales tax. Built to order; sample lead time 6–8 weeks.</p>
            <div className={styles.actions}>
              <button type="button" className={styles.primary} onClick={() => setRequested(true)}>Request this build</button>
              <button type="button" className={styles.secondary} onClick={copyLink}>Copy link to this build</button>
              <button type="button" className={styles.textBtn} onClick={reset}>Reset to the standard build</button>
            </div>
            <div className={styles.feedback} aria-live="polite">
              {requested ? <p className={styles.sent}>Demo only: nothing was sent. A real shop would open its build-slot form here with {code} attached.</p> : null}
              {copied === 'copied' ? <p className={styles.sent}>Link copied. Anyone who opens it sees this exact build.</p> : null}
            </div>
            {copied === 'manual' ? (
              <p className={styles.manual}>
                <label htmlFor={`${uid}link`}>Copying isn’t available here. Select the link and copy it:</label>
                <input id={`${uid}link`} ref={linkField} className={styles.linkField} readOnly value={typeof window === 'undefined' ? '' : window.location.href} />
              </p>
            ) : null}
          </section>
        </form>
      </div>

      <section className={styles.why} aria-labelledby={`${uid}why`}>
        <div className={styles.whyHead}>
          <p className={styles.kicker}>Why this configurator is a drawing</p>
          <h2 id={`${uid}why`} className={styles.whyTitle}>Bikes are chosen side-on, so we drew one.</h2>
        </div>
        <ol className={styles.reasons}>
          <li>
            <span className={styles.reasonNum} aria-hidden="true">01</span>
            <h3>Every choice shows from one side</h3>
            <p>Fit, tyre clearance, bar shape and where a rack sits are all side-elevation questions. Geometry charts, frame builders’ sketches and catalogue photos have always been drawn this way; turning the bike over answers nothing new.</p>
          </li>
          <li>
            <span className={styles.reasonNum} aria-hidden="true">02</span>
            <h3>{combos.toLocaleString('en-US')} builds, one drawing</h3>
            <p>Four sizes, two frames, four paints, three bars, three tyres and three extras make {combos.toLocaleString('en-US')} valid builds once the fender rule is applied. Too many to photograph, but each is just numbers, so the page draws it from the geometry table.</p>
          </li>
          <li>
            <span className={styles.reasonNum} aria-hidden="true">03</span>
            <h3>Nothing to download or wait for</h3>
            <p>It is SVG generated in the page: no model file, no WebGL context, no loading state. It stays sharp at any size, prints cleanly, and works on any device that can show this text.</p>
          </li>
        </ol>
        <aside className={styles.compare} aria-label="When 3D is worth it">
          <p>When an object has to be turned over (ports underneath, a strap behind, parts that come apart), real-time 3D earns its download and GPU cost. The 3D Studio’s speaker configurator is that case.</p>
          <a className={styles.compareLink} href="/demos/3d/product-configurator">View in 3D: the Pulse speaker configurator<span aria-hidden="true"> →</span></a>
        </aside>
      </section>

      <footer className={styles.colophon}>
        <p>Hollin Cycles and the {MODEL} are fictional. Geometry, prices and lead times are sample data for this demo.</p>
      </footer>

      <p className={styles.srOnly} role="status">{status}</p>
    </div>
  );
}

/**
 * Hollin Drover — option data and the parametric side elevation.
 * Everything here is fictional sample data (brand, geometry, prices, lead time).
 * Units are millimetres, origin at the bottom bracket, +x forward, +y up.
 */

export type SizeId = '50' | '53' | '56' | '59';
export type FrameId = 'steel' | 'titanium';
export type PaintId = 'fern' | 'slate' | 'marigold' | 'chalk';
export type BarId = 'drop' | 'flat' | 'swept';
export type TyreId = 'road38' | 'tan38' | 'gravel45';
export type ExtraId = 'fenders' | 'rack' | 'lights';

export interface Build { size: SizeId; frame: FrameId; paint: PaintId; bar: BarId; tyre: TyreId; extras: readonly ExtraId[] }

export interface Choice<Id extends string> { id: Id; name: string; note: string; price: number; code: string }

export interface SizeSpec extends Choice<SizeId> {
  rider: string;
  /** seat tube (centre–top), head tube, stack, reach, head/seat angles, saddle height, stem length */
  st: number; ht: number; stack: number; reach: number; hta: number; sta: number; saddle: number; stem: number;
}

export const BASE_PRICE = 1890;
export const MODEL = 'Drover';

export const SIZES: SizeSpec[] = [
  { id: '50', name: '50', code: '50', note: 'Riders about 158–168 cm', rider: '158–168', price: 0, st: 500, ht: 115, stack: 548, reach: 372, hta: 71, sta: 74, saddle: 672, stem: 80 },
  { id: '53', name: '53', code: '53', note: 'Riders about 166–176 cm', rider: '166–176', price: 0, st: 530, ht: 135, stack: 568, reach: 380, hta: 71.5, sta: 73.5, saddle: 708, stem: 90 },
  { id: '56', name: '56', code: '56', note: 'Riders about 174–184 cm', rider: '174–184', price: 0, st: 560, ht: 160, stack: 592, reach: 388, hta: 72, sta: 73, saddle: 745, stem: 100 },
  { id: '59', name: '59', code: '59', note: 'Riders about 182–192 cm', rider: '182–192', price: 0, st: 590, ht: 185, stack: 616, reach: 396, hta: 72, sta: 72.5, saddle: 782, stem: 110 },
];

export const FRAMES: Choice<FrameId>[] = [
  { id: 'steel', name: 'Chromoly steel', code: 'CR', note: 'Brazed, painted, repairable almost anywhere.', price: 0 },
  { id: 'titanium', name: 'Titanium', code: 'TI', note: 'Bead-blasted and left raw. Lighter, never rusts.', price: 1150 },
];

export interface Paint extends Choice<PaintId> { colour: string }
export const PAINTS: Paint[] = [
  { id: 'fern', name: 'Fern', code: 'FE', note: 'Deep green, gloss', price: 0, colour: '#3f6b4c' },
  { id: 'slate', name: 'Slate', code: 'SL', note: 'Blue-grey, satin', price: 0, colour: '#4a5866' },
  { id: 'marigold', name: 'Marigold', code: 'MG', note: 'Two-coat pearl', price: 60, colour: '#d39a26' },
  { id: 'chalk', name: 'Chalk', code: 'CH', note: 'Two-coat off-white', price: 60, colour: '#e7e1d2' },
];

export const BARS: Choice<BarId>[] = [
  { id: 'drop', name: 'Drop bar', code: 'DB', note: 'Three hand positions for long days.', price: 0 },
  { id: 'flat', name: 'Flat bar', code: 'FB', note: 'Upright, simpler levers.', price: -40 },
  { id: 'swept', name: 'Swept bar', code: 'SB', note: 'Sits you up, wrists relaxed.', price: 35 },
];

export interface Tyre extends Choice<TyreId> { width: number; tan: boolean }
export const TYRES: Tyre[] = [
  { id: 'road38', name: '38 mm all-road', code: 'R38', note: 'Black, fast on tarmac', price: 0, width: 38, tan: false },
  { id: 'tan38', name: '38 mm tan wall', code: 'T38', note: 'Same tread, tan sidewall', price: 18, width: 38, tan: true },
  { id: 'gravel45', name: '45 mm gravel', code: 'G45', note: 'Knobbed, for loose ground', price: 30, width: 45, tan: false },
];

export const EXTRAS: Choice<ExtraId>[] = [
  { id: 'fenders', name: 'Full-length fenders', code: 'F', note: 'Aluminium blades with mudflap.', price: 95 },
  { id: 'rack', name: 'Rear rack', code: 'R', note: 'Steel, rated for 25 kg of bags.', price: 140 },
  { id: 'lights', name: 'Dynamo lighting', code: 'L', note: 'Hub dynamo, front and rear lights.', price: 265 },
];

/** The one hard incompatibility: fender blades clear tyres up to 40 mm. */
export const FENDER_MAX_TYRE = 40;
export const fendersFit = (tyre: TyreId): boolean => (TYRES.find((t) => t.id === tyre)?.width ?? 0) <= FENDER_MAX_TYRE;

export const DEFAULT_BUILD: Build = { size: '56', frame: 'steel', paint: 'fern', bar: 'drop', tyre: 'road38', extras: [] };

const byId = <T extends { id: string }>(list: readonly T[], id: string): T => list.find((x) => x.id === id) ?? list[0];
export const sizeOf = (b: Build) => byId(SIZES, b.size);
export const frameOf = (b: Build) => byId(FRAMES, b.frame);
export const paintOf = (b: Build) => byId(PAINTS, b.paint);
export const barOf = (b: Build) => byId(BARS, b.bar);
export const tyreOf = (b: Build) => byId(TYRES, b.tyre);

export function priceOf(b: Build): number {
  return BASE_PRICE + frameOf(b).price + paintOf(b).price + barOf(b).price + tyreOf(b).price
    + EXTRAS.filter((e) => b.extras.includes(e.id)).reduce((s, e) => s + e.price, 0);
}

export function codeOf(b: Build): string {
  const extras = EXTRAS.filter((e) => b.extras.includes(e.id)).map((e) => e.code).join('') || '0';
  return ['DRV', sizeOf(b).code, frameOf(b).code, paintOf(b).code, barOf(b).code, tyreOf(b).code, extras].join('-');
}

/** Every valid combination, counted from the option data (so the number in the copy is never typed by hand). */
export function countBuilds(): number {
  let n = 0;
  const extraSets = 1 << EXTRAS.length;
  for (const tyre of TYRES) {
    for (let mask = 0; mask < extraSets; mask++) {
      const hasFenders = EXTRAS.some((e, i) => e.id === 'fenders' && mask & (1 << i));
      if (hasFenders && !fendersFit(tyre.id)) continue;
      n += SIZES.length * FRAMES.length * PAINTS.length * BARS.length;
    }
  }
  return n;
}

/* ── URL hash ───────────────────────────────────────────────────────────── */

const isIn = <T extends string>(list: readonly { id: T }[], v: string | null): v is T => !!v && list.some((x) => x.id === v);

export function toHash(b: Build): string {
  const p = new URLSearchParams({ size: b.size, frame: b.frame, paint: b.paint, bar: b.bar, tyre: b.tyre, extras: b.extras.join('.') || 'none' });
  return `#${p.toString()}`;
}

export function fromHash(hash: string): Build | null {
  if (!hash || hash.length < 2) return null;
  const p = new URLSearchParams(hash.slice(1));
  if (!p.has('size')) return null;
  const pick = <T extends string>(key: string, list: readonly { id: T }[], fallback: T): T => { const v = p.get(key); return isIn(list, v) ? v : fallback; };
  const tyre = pick('tyre', TYRES, DEFAULT_BUILD.tyre);
  const extras = (p.get('extras') ?? '').split('.').filter((x): x is ExtraId => isIn(EXTRAS, x))
    .filter((x) => x !== 'fenders' || fendersFit(tyre));
  return {
    size: pick('size', SIZES, DEFAULT_BUILD.size),
    frame: pick('frame', FRAMES, DEFAULT_BUILD.frame),
    paint: pick('paint', PAINTS, DEFAULT_BUILD.paint),
    bar: pick('bar', BARS, DEFAULT_BUILD.bar),
    tyre,
    extras: EXTRAS.map((e) => e.id).filter((id) => extras.includes(id)),
  };
}

export const sameBuild = (a: Build, b: Build): boolean => toHash(a) === toHash(b);

/* ── Geometry ───────────────────────────────────────────────────────────── */

export interface Pt { x: number; y: number }
/** The numbers the drawing is computed from; tweened as a whole when the size or tyre changes. */
export interface Fit { st: number; ht: number; stack: number; reach: number; hta: number; sta: number; saddle: number; stem: number; tyre: number }

export const fitOf = (b: Build): Fit => {
  const s = sizeOf(b);
  return { st: s.st, ht: s.ht, stack: s.stack, reach: s.reach, hta: s.hta, sta: s.sta, saddle: s.saddle, stem: s.stem, tyre: tyreOf(b).width };
};

export const CHAINSTAY = 450;
export const BB_DROP = 72;
export const FORK_OFFSET = 50;
/** ISO 622 bead seat radius (700C). */
export const RIM_R = 311;

const rad = (d: number) => (d * Math.PI) / 180;
export const pt = (x: number, y: number): Pt => ({ x, y });
export const along = (from: Pt, dir: Pt, len: number): Pt => ({ x: from.x + dir.x * len, y: from.y + dir.y * len });
export const lerp = (a: Pt, b: Pt, t: number): Pt => ({ x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t });

export interface Solved {
  bb: Pt; rear: Pt; front: Pt; stTop: Pt; htTop: Pt; htBot: Pt;
  stDir: Pt; down: Pt; perp: Pt; forkLen: number;
  radius: number; ground: number; wheelbase: number;
  seatCluster: Pt; ssTop: Pt; ttFront: Pt; dtFront: Pt; crown: Pt; forkCtrl: Pt;
  saddle: Pt; postTop: Pt; steererTop: Pt; clamp: Pt;
}

export function solve(f: Fit): Solved {
  const bb = pt(0, 0);
  const rear = pt(-Math.sqrt(CHAINSTAY ** 2 - BB_DROP ** 2), BB_DROP);
  const stDir = pt(-Math.cos(rad(f.sta)), Math.sin(rad(f.sta)));
  const stTop = along(bb, stDir, f.st);
  const down = pt(Math.cos(rad(f.hta)), -Math.sin(rad(f.hta)));
  const perp = pt(Math.sin(rad(f.hta)), Math.cos(rad(f.hta)));
  const htTop = pt(f.reach, f.stack);
  const htBot = along(htTop, down, f.ht);
  // Fork: the axle sits FORK_OFFSET ahead of the steering axis, level with the rear axle.
  const forkLen = (htBot.y + FORK_OFFSET * perp.y - BB_DROP) / Math.sin(rad(f.hta));
  const axis = along(htBot, down, forkLen);
  const front = along(axis, perp, FORK_OFFSET);
  const radius = RIM_R + f.tyre;
  const stem = pt(Math.cos(rad(8)), Math.sin(rad(8)));
  const steererTop = along(htTop, down, -24);
  return {
    bb, rear, front, stTop, htTop, htBot, stDir, down, perp, forkLen,
    radius, ground: BB_DROP - radius, wheelbase: front.x - rear.x,
    seatCluster: along(bb, stDir, f.st - 22),
    ssTop: along(bb, stDir, f.st - 36),
    ttFront: along(htTop, down, 26),
    dtFront: along(htBot, down, -34),
    crown: along(htBot, down, 16),
    forkCtrl: along(htBot, down, forkLen * 0.8),
    saddle: along(bb, stDir, f.saddle),
    postTop: along(bb, stDir, f.saddle - 34),
    steererTop,
    clamp: along(steererTop, stem, f.stem),
  };
}

/** The fixed drawing frame (largest size, widest tyre) so sizes compare at true scale. */
export const VIEW = { minX: -880, maxX: 1060, minY: -400, maxY: 810 } as const;
export const VIEW_W = VIEW.maxX - VIEW.minX;
export const VIEW_H = VIEW.maxY - VIEW.minY;
/** Model point → percentage position inside the drawing box (for HTML labels laid over the SVG). */
export const toPct = (p: Pt) => ({ left: `${((p.x - VIEW.minX) / VIEW_W) * 100}%`, top: `${((VIEW.maxY - p.y) / VIEW_H) * 100}%` });

export function interpolateFit(a: Fit, b: Fit, t: number): Fit {
  const out = {} as Fit;
  for (const k of Object.keys(b) as (keyof Fit)[]) out[k] = a[k] + (b[k] - a[k]) * t;
  return out;
}

export const formatPrice = (n: number): string => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(n);
export const formatDelta = (n: number): string => (n === 0 ? 'Included' : `${n > 0 ? '+' : '−'}${formatPrice(Math.abs(n))}`);
export const mm = (n: number): string => new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 }).format(n);

'use client';
import {
  RIM_R, VIEW, VIEW_H, VIEW_W, along, frameOf, lerp, mm, paintOf, pt, sizeOf, solve, toPct, tyreOf, barOf,
  type BarId, type Build, type ExtraId, type Fit, type Pt,
} from './bike';
import styles from './styles.module.css';

/* Model (y up) → SVG user units (y down). */
const P = (p: Pt) => `${p.x.toFixed(1)} ${(-p.y).toFixed(1)}`;
const off = (c: Pt, dx: number, dy: number): Pt => pt(c.x + dx, c.y + dy);
const seg = (a: Pt, b: Pt) => `M${P(a)}L${P(b)}`;
const onCircle = (c: Pt, r: number, deg: number): Pt => pt(c.x + r * Math.cos((deg * Math.PI) / 180), c.y + r * Math.sin((deg * Math.PI) / 180));

function arc(c: Pt, r: number, a0: number, a1: number, steps = 36): string {
  let d = '';
  for (let i = 0; i <= steps; i++) d += `${i ? 'L' : 'M'}${P(onCircle(c, r, a0 + ((a1 - a0) * i) / steps))}`;
  return d;
}

function spokes(c: Pt, hub: number, rim: number, n = 32): string {
  let d = '';
  for (let i = 0; i < n; i++) {
    const a = (i / n) * 360;
    d += `M${P(onCircle(c, hub, a))}L${P(onCircle(c, rim, a + (i % 2 ? 28 : -28)))}`;
  }
  return d;
}

/** External tangent between two circles (chain runs). side −1 = upper run, +1 = lower run for bb → rear. */
function tangent(c1: Pt, r1: number, c2: Pt, r2: number, side: 1 | -1): [Pt, Pt] {
  const dx = c2.x - c1.x, dy = c2.y - c1.y, d = Math.hypot(dx, dy), th = Math.atan2(dy, dx);
  const a = th + side * Math.acos(Math.max(-1, Math.min(1, (r1 - r2) / d)));
  return [pt(c1.x + r1 * Math.cos(a), c1.y + r1 * Math.sin(a)), pt(c2.x + r2 * Math.cos(a), c2.y + r2 * Math.sin(a))];
}

type Tone = 'tape' | 'metal';
interface Stroke { d: string; w: number; tone: Tone }

/** Handlebar silhouettes relative to the stem clamp — shared by the drawing and the option pictograms. */
export function barStrokes(id: BarId, c: Pt): Stroke[] {
  if (id === 'flat') {
    return [
      { d: seg(off(c, 8, 0), off(c, 98, -24)), w: 9, tone: 'metal' },
      { d: seg(off(c, -4, -16), off(c, 12, -30)), w: 14, tone: 'tape' },
      { d: seg(off(c, -2, 2), off(c, 4, 2)), w: 36, tone: 'tape' },
    ];
  }
  if (id === 'swept') {
    return [
      { d: `M${P(c)}C${P(off(c, -30, 8))} ${P(off(c, -92, 22))} ${P(off(c, -150, 20))}`, w: 22, tone: 'metal' },
      { d: seg(off(c, -140, 14), off(c, -104, -22)), w: 9, tone: 'metal' },
      { d: seg(off(c, -150, 20), off(c, -214, 15)), w: 32, tone: 'tape' },
    ];
  }
  return [
    { d: `M${P(off(c, -6, 0))}L${P(off(c, 44, 2))}C${P(off(c, 96, 4))} ${P(off(c, 112, -46))} ${P(off(c, 96, -86))}C${P(off(c, 84, -114))} ${P(off(c, 56, -128))} ${P(off(c, 24, -126))}C${P(off(c, 6, -125))} ${P(off(c, -6, -118))} ${P(off(c, -10, -110))}`, w: 24, tone: 'tape' },
    { d: `M${P(off(c, 88, -12))}C${P(off(c, 100, -48))} ${P(off(c, 94, -80))} ${P(off(c, 80, -98))}`, w: 9, tone: 'metal' },
    { d: seg(off(c, 52, 8), off(c, 84, -4)), w: 30, tone: 'tape' },
  ];
}

/** Small side-on pictogram of a handlebar for the option cards. */
export function BarIcon({ id }: { id: BarId }) {
  const c = pt(0, 0);
  return (
    <svg className={styles.barIcon} viewBox="-235 -40 365 180" aria-hidden="true" focusable="false">
      <path d={seg(pt(-99, -14), c)} className={styles.icStem} strokeWidth={30} />
      {barStrokes(id, c).map((s, i) => <path key={i} d={s.d} strokeWidth={s.w + 10} className={styles.icOutline} />)}
      {barStrokes(id, c).map((s, i) => <path key={i} d={s.d} strokeWidth={s.w} className={s.tone === 'tape' ? styles.icTape : styles.icMetal} />)}
    </svg>
  );
}

const BARS: BarId[] = ['drop', 'flat', 'swept'];

export function describeBuild(b: Build): string {
  const extras = b.extras.length
    ? `, fitted with ${b.extras.map((e) => ({ fenders: 'full-length fenders', rack: 'a rear rack', lights: 'dynamo lighting' })[e]).join(' and ')}`
    : ', no extras';
  const paint = b.frame === 'titanium' ? `raw titanium frame with a ${paintOf(b).name} fork` : `chromoly steel frame in ${paintOf(b).name}`;
  return `Size ${sizeOf(b).name}: ${paint}, ${barOf(b).name.toLowerCase()}, ${tyreOf(b).name} tyres${extras}.`;
}

export function BikeDrawing({ build, fit, uid }: { build: Build; fit: Fit; uid: string }) {
  const s = solve(fit);
  const titanium = frameOf(build).id === 'titanium';
  const paint = paintOf(build);
  const tyre = tyreOf(build);
  const has = (e: ExtraId) => build.extras.includes(e);
  const frameColour = titanium ? 'var(--hc-ti)' : paint.colour;
  const lightPaint = titanium || paint.id === 'chalk' || paint.id === 'marigold';

  const tubes = [
    { k: 'cs', a: s.bb, b: s.rear, d: 19 },
    { k: 'ss', a: s.ssTop, b: s.rear, d: 16 },
    { k: 'st', a: s.bb, b: s.stTop, d: 28.6 },
    { k: 'tt', a: s.seatCluster, b: s.ttFront, d: 28.6 },
    { k: 'dt', a: s.bb, b: s.dtFront, d: 31.8 },
    { k: 'ht', a: along(s.htTop, s.down, -8), b: along(s.htBot, s.down, 6), d: 36 },
  ];
  const fork = `M${P(s.crown)}Q${P(s.forkCtrl)} ${P(s.front)}`;
  const crown = seg(s.htBot, along(s.htBot, s.down, 24));

  // Drivetrain
  const ringR = 89, cogR = 40;
  const upper = tangent(s.bb, ringR, s.rear, cogR, -1);
  const jockeyHi = off(s.rear, 8, -44), jockeyLo = off(s.rear, 22, -92);
  const lower = tangent(s.bb, ringR, jockeyLo, 13, 1);
  const crankEnd = onCircle(s.bb, 170, -38);

  // Fitted extras
  const fenderR = s.radius + 14;
  const platY = s.rear.y + s.radius + 52;
  const rackRear = pt(s.rear.x - 140, platY), rackFront = pt(s.rear.x + 132, platY);
  const t = Math.min(0.98, Math.max(0, (platY + 14 - s.rear.y) / (s.ssTop.y - s.rear.y)));
  const rackAttach = lerp(s.rear, s.ssTop, t);
  const eyelet = off(s.rear, -18, 26);
  const headlight = along(along(s.htBot, s.down, 26), s.perp, 46);
  const tail = has('rack') ? off(rackRear, -6, -26) : has('fenders') ? onCircle(s.rear, fenderR + 4, 168) : along(s.bb, s.stDir, fit.st + 60);

  // Dimension lines (labels are HTML, laid over the drawing)
  const wbY = s.ground - 70;
  const dtAngle = (Math.atan2(s.dtFront.y - s.bb.y, s.dtFront.x - s.bb.x) * 180) / Math.PI;
  const decal = lerp(s.bb, s.dtFront, 0.56);

  return (
    <div className={styles.drawing}>
      <svg className={styles.svg} viewBox={`${VIEW.minX} ${-VIEW.maxY} ${VIEW_W} ${VIEW_H}`} role="img" aria-labelledby={`${uid}-dt ${uid}-dd`} preserveAspectRatio="xMidYMid meet">
        <title id={`${uid}-dt`}>Side elevation of the Hollin Drover</title>
        <desc id={`${uid}-dd`}>{`${describeBuild(build)} Stack ${mm(fit.stack)} mm, reach ${mm(fit.reach)} mm, wheelbase ${mm(s.wheelbase)} mm.`}</desc>

        <path d={seg(pt(VIEW.minX + 40, s.ground), pt(VIEW.maxX - 40, s.ground))} className={styles.ground} />

        {[s.rear, s.front].map((c, i) => (
          <g key={i}>
            <circle cx={c.x} cy={-c.y} r={RIM_R - 7} strokeWidth={14} className={styles.rim} />
            <path d={spokes(c, i === 1 && has('lights') ? 26 : 18, RIM_R - 14)} className={styles.spokes} />
            <circle cx={c.x} cy={-c.y} r={i === 1 && has('lights') ? 30 : i === 0 ? 22 : 17} className={styles.hub} />
            <circle cx={c.x} cy={-c.y} r={s.radius - fit.tyre / 2} strokeWidth={fit.tyre} className={styles.tyre} />
            <circle cx={c.x} cy={-c.y} r={s.radius - fit.tyre * 0.68} strokeWidth={fit.tyre * 0.5} className={`${styles.part} ${styles.tan}`} data-on={tyre.tan} />
            <circle cx={c.x} cy={-c.y} r={s.radius - 3} strokeWidth={10} strokeDasharray="11 9" className={`${styles.part} ${styles.knobs}`} data-on={tyre.id === 'gravel45'} />
            <circle cx={c.x} cy={-c.y} r={s.radius + 1} className={styles.edge} />
            <circle cx={c.x} cy={-c.y} r={s.radius - fit.tyre - 1} className={styles.edge} />
          </g>
        ))}

        <g className={`${styles.part} ${styles.lift}`} data-on={has('fenders')}>
          <path d={arc(s.front, fenderR, 208, 18)} strokeWidth={17} className={styles.outline} />
          <path d={arc(s.rear, fenderR, 172, 4)} strokeWidth={17} className={styles.outline} />
          <path d={arc(s.front, fenderR, 208, 18)} strokeWidth={11} className={styles.alloy} />
          <path d={arc(s.rear, fenderR, 172, 4)} strokeWidth={11} className={styles.alloy} />
          <path d={seg(onCircle(s.front, fenderR, 208), onCircle(s.front, fenderR + 70, 214))} strokeWidth={9} className={styles.rubber} />
          <path d={`${seg(onCircle(s.front, fenderR - 4, 200), s.front)}${seg(onCircle(s.rear, fenderR - 4, 160), s.rear)}`} className={styles.stay} />
        </g>

        <g className={`${styles.part} ${styles.lift}`} data-on={has('rack')}>
          <path d={`${seg(rackRear, rackFront)}${seg(off(rackRear, 20, 0), eyelet)}${seg(off(rackRear, 170, 0), eyelet)}${seg(rackFront, rackAttach)}`} strokeWidth={11} className={styles.rack} />
        </g>

        <path d={seg(along(s.bb, s.stDir, fit.st - 40), s.postTop)} strokeWidth={27} className={styles.metalOutlined} />

        <g>
          {tubes.map((tb) => <path key={tb.k} d={seg(tb.a, tb.b)} strokeWidth={tb.d + 7} className={styles.outline} />)}
          <path d={fork} strokeWidth={29} className={styles.outline} />
          <path d={crown} strokeWidth={47} className={styles.outline} />
          <circle cx={s.bb.x} cy={-s.bb.y} r={26.5} className={styles.outlineFill} />
          <circle cx={s.rear.x} cy={-s.rear.y} r={18.5} className={styles.outlineFill} />

          {tubes.map((tb) => <path key={tb.k} d={seg(tb.a, tb.b)} strokeWidth={tb.d} className={styles.paint} style={{ stroke: frameColour }} />)}
          <circle cx={s.bb.x} cy={-s.bb.y} r={23} className={styles.paintFill} style={{ fill: frameColour }} />
          <circle cx={s.rear.x} cy={-s.rear.y} r={15} className={styles.paintFill} style={{ fill: frameColour }} />
          <path d={fork} strokeWidth={22} className={styles.paint} style={{ stroke: paint.colour }} />
          <path d={crown} strokeWidth={40} className={styles.paint} style={{ stroke: paint.colour }} />
          <circle cx={s.front.x} cy={-s.front.y} r={14} className={styles.paintFill} style={{ fill: paint.colour }} />

          <g className={styles.part} data-on={titanium}>
            {tubes.filter((tb) => tb.k !== 'ht').map((tb) => {
              const n = (() => { const dx = tb.b.x - tb.a.x, dy = tb.b.y - tb.a.y, l = Math.hypot(dx, dy) || 1; return pt(-dy / l, dx / l); })();
              const k = tb.d * 0.22;
              return <path key={tb.k} d={seg(lerp(along(tb.a, n, k), along(tb.b, n, k), 0.08), lerp(along(tb.a, n, k), along(tb.b, n, k), 0.92))} strokeWidth={tb.d * 0.14} className={styles.tiShine} />;
            })}
          </g>

          <circle cx={along(lerp(s.htTop, s.htBot, 0.4), s.perp, 19).x} cy={-along(lerp(s.htTop, s.htBot, 0.4), s.perp, 19).y} r={9} className={styles.badge} />
          <text className={styles.decal} data-light={lightPaint} transform={`translate(${decal.x.toFixed(1)} ${(-decal.y).toFixed(1)}) rotate(${(-dtAngle).toFixed(2)})`}>HOLLIN</text>
        </g>

        <g>
          <path d={`${seg(upper[0], upper[1])}${seg(lower[0], lower[1])}${seg(off(jockeyLo, -13, 0), off(jockeyHi, -13, 0))}${seg(off(jockeyHi, 13, 0), onCircle(s.rear, cogR, 290))}`} className={styles.chain} strokeWidth={8} />
          <path d={seg(off(s.rear, 6, -10), jockeyLo)} strokeWidth={14} className={styles.mech} />
          <circle cx={jockeyHi.x} cy={-jockeyHi.y} r={13} className={styles.jockey} />
          <circle cx={jockeyLo.x} cy={-jockeyLo.y} r={13} className={styles.jockey} />
          <circle cx={s.rear.x} cy={-s.rear.y} r={cogR} strokeWidth={7} className={styles.cog} />
          <circle cx={s.bb.x} cy={-s.bb.y} r={ringR} strokeWidth={12} className={styles.ring} />
          <circle cx={s.bb.x} cy={-s.bb.y} r={ringR + 7} strokeWidth={7} strokeDasharray="5 5" className={styles.ring} />
          <path d={seg(s.bb, crankEnd)} strokeWidth={30} className={styles.outline} />
          <path d={seg(s.bb, crankEnd)} strokeWidth={23} className={styles.crank} />
          <circle cx={s.bb.x} cy={-s.bb.y} r={14} className={styles.hub} />
          <path d={seg(off(crankEnd, -44, -6), off(crankEnd, 44, -6))} strokeWidth={22} className={styles.rubber} />
        </g>

        <g>
          <path d={`M${P(off(s.saddle, -150, -18))}C${P(off(s.saddle, -152, 2))} ${P(off(s.saddle, -110, 6))} ${P(off(s.saddle, -40, 2))}L${P(off(s.saddle, 110, -6))}C${P(off(s.saddle, 122, -8))} ${P(off(s.saddle, 124, -20))} ${P(off(s.saddle, 112, -24))}L${P(off(s.saddle, -30, -30))}C${P(off(s.saddle, -100, -36))} ${P(off(s.saddle, -148, -36))} ${P(off(s.saddle, -150, -18))}Z`} className={styles.saddle} />
          <path d={seg(off(s.saddle, -70, -40), off(s.saddle, 70, -36))} strokeWidth={7} className={styles.alloy} />
          <path d={seg(along(s.htTop, s.down, -2), along(s.htTop, s.down, -40))} strokeWidth={30} className={styles.metalOutlined} />
          <path d={seg(s.steererTop, s.clamp)} strokeWidth={34} className={styles.outline} />
          <path d={seg(s.steererTop, s.clamp)} strokeWidth={28} className={styles.stem} />
          {BARS.map((id) => (
            <g key={id} className={styles.part} data-on={build.bar === id}>
              {barStrokes(id, s.clamp).map((st, i) => <path key={`o${i}`} d={st.d} strokeWidth={st.w + 7} className={styles.outline} />)}
              {barStrokes(id, s.clamp).map((st, i) => <path key={`f${i}`} d={st.d} strokeWidth={st.w} className={st.tone === 'tape' ? styles.tape : styles.alloy} />)}
            </g>
          ))}
        </g>

        <g className={`${styles.part} ${styles.lift}`} data-on={has('lights')}>
          <path d={`M${P(off(s.front, -8, 28))}Q${P(off(s.forkCtrl, -16, 0))} ${P(along(s.crown, s.perp, 14))}`} className={styles.wire} />
          <path d={seg(along(s.htBot, s.down, 22), headlight)} strokeWidth={8} className={styles.alloy} />
          <rect x={headlight.x - 26} y={-headlight.y - 15} width={52} height={30} rx={9} className={styles.lamp} />
          <circle cx={headlight.x + 22} cy={-headlight.y} r={11} className={styles.lens} />
          <rect x={tail.x - 13} y={-tail.y - 20} width={26} height={40} rx={7} className={styles.tail} />
        </g>

        <g className={styles.dimLines}>
          <path d={`${seg(off(s.rear, 0, -s.radius - 14), pt(s.rear.x, wbY - 18))}${seg(off(s.front, 0, -s.radius - 14), pt(s.front.x, wbY - 18))}`} className={styles.ext} />
          <path d={`${seg(pt(s.rear.x, wbY), pt(s.front.x, wbY))}${seg(pt(s.rear.x, wbY - 14), pt(s.rear.x, wbY + 14))}${seg(pt(s.front.x, wbY - 14), pt(s.front.x, wbY + 14))}`} className={styles.dim} />
          <path d={`${seg(pt(s.htTop.x, 0), pt(s.htTop.x, s.htTop.y))}${seg(pt(s.htTop.x - 14, 0), pt(s.htTop.x + 14, 0))}${seg(pt(0, s.htTop.y), pt(s.htTop.x, s.htTop.y))}${seg(pt(0, s.htTop.y - 14), pt(0, s.htTop.y + 14))}`} className={styles.dim} />
          <path d={seg(pt(0, 0), pt(0, s.htTop.y - 14))} className={styles.ext} />
        </g>
      </svg>

      <div className={styles.dims} aria-hidden="true">
        <span className={styles.dimLabel} data-align="start" style={toPct(pt(s.htTop.x + 22, s.htTop.y * 0.5))}>Stack <b>{mm(fit.stack)}</b></span>
        <span className={styles.dimLabel} data-align="center" style={toPct(pt(s.htTop.x * 0.5, s.htTop.y + 40))}>Reach <b>{mm(fit.reach)}</b></span>
        <span className={styles.dimLabel} data-align="center" style={toPct(pt((s.rear.x + s.front.x) / 2, wbY - 44))}>Wheelbase <b>{mm(s.wheelbase)}</b></span>
      </div>
    </div>
  );
}

/* Hollin Drover — a frame builder's drawing table.
   Ink linework on drafting paper, dimension lines in the signal colour, mono labels, one heavy grotesque for the
   model name. Paint colours are product content; every UI colour comes from the theme tokens. */

.root {
  --hc-line: var(--mk-ink, #11110f);
  --hc-metal: #a5a7a2;
  --hc-spoke: #767873;
  --hc-rubber: #242421;
  --hc-tan: #c4955a;
  --hc-ti: #b9bab4;
  --hc-ti-hi: #f1f1ec;
  --hc-brass: #b98a35;
  --hc-lens: #f4ead0;
  --hc-tail: #c4361f;
  --hc-grid: color-mix(in oklab, var(--mk-ink, #11110f) 6%, transparent);
  --plate-h: calc((100cqi - 32px) / 1.603 + 92px);
  background: var(--mk-bg, #f3f0e8);
  color: var(--mk-ink, #11110f);
  font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
  overflow-x: clip;
}
:global([data-theme='dark']) .root {
  --hc-metal: #92948f;
  --hc-spoke: #8d8f8a;
  --hc-rubber: #3b3a36;
  --hc-ti: #a9aaa4;
  --hc-ti-hi: #e3e4de;
}

.srOnly {
  position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

/* ── Layout: plate (sticky) + intro + options ─────────────────────────── */
.layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-areas: 'intro' 'plate' 'options';
  column-gap: clamp(28px, 4cqi, 72px);
  max-width: 1520px;
  margin-inline: auto;
  padding-inline: 16px;
}
.intro { grid-area: intro; padding-block: 28px 18px; }
.plate {
  grid-area: plate;
  position: sticky;
  top: 44px;
  z-index: 3;
  align-self: start;
  margin-inline: -16px;
  padding: 6px 16px 10px;
  background: var(--mk-bg, #f3f0e8);
  border-block: 1px solid var(--mk-line, #11110f24);
}
.options { grid-area: options; padding-bottom: 32px; }

@container (min-width: 960px) {
  .layout { grid-template-columns: minmax(0, 1.62fr) minmax(360px, 1fr); grid-template-areas: 'plate intro' 'plate options'; grid-template-rows: auto 1fr; padding-inline: 32px; }
  .intro { padding-block: 40px 12px; }
  .plate {
    margin-inline: 0;
    padding: 20px 0 24px;
    border-block: 0;
    height: calc(100dvh - 44px);
    max-height: 980px;
    display: flex;
    flex-direction: column;
  }
}

/* ── Intro ─────────────────────────────────────────────────────────────── */
.brand { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: 0; }
.wordmark { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; letter-spacing: 0.14em; text-transform: uppercase; }
.tag {
  font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.08em; text-transform: uppercase;
  border: 1px solid var(--mk-line-strong, #11110f); border-radius: 999px; padding: 3px 9px;
}
.model {
  margin: 14px 0 0;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-weight: 800;
  font-size: clamp(4rem, 1.5rem + 11cqi, 7.25rem);
  line-height: 0.8;
  letter-spacing: -0.065em;
  margin-left: -0.04em;
}
.lede { margin: 18px 0 0; max-width: 40ch; font-size: 1rem; line-height: 1.5; color: var(--mk-ink-muted, #5c5a52); text-wrap: pretty; }

/* ── Plate: the drawing ────────────────────────────────────────────────── */
.plateHead { display: none; }
.plateTitle, .code {
  margin: 0; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; font-weight: 400; letter-spacing: 0.08em; text-transform: uppercase;
}
.code { letter-spacing: 0.04em; font-variant-numeric: tabular-nums; color: var(--mk-ink-muted, #5c5a52); }
.drawingWrap { display: grid; place-items: center; min-height: 0; }
.drawing {
  position: relative;
  width: 100%;
  aspect-ratio: 1940 / 1210;
  background-color: var(--mk-surface, #fbf9f4);
  background-image:
    linear-gradient(var(--hc-grid) 1px, transparent 1px),
    linear-gradient(90deg, var(--hc-grid) 1px, transparent 1px);
  background-size: 24px 24px;
  background-position: -1px -1px;
  border: 1px solid var(--mk-line, #11110f24);
  border-radius: var(--mk-radius-s, 4px);
}
.svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.caption { display: none; }

@container (min-width: 960px) {
  .plateHead { display: flex; justify-content: space-between; gap: 16px; padding-bottom: 12px; border-bottom: 1px solid var(--mk-line, #11110f24); margin-bottom: 16px; }
  .drawingWrap { flex: 1 1 auto; }
  .drawing { width: min(100%, calc((min(100dvh, 980px) - 44px - 250px) * 1.603)); }
  .caption { display: block; margin: 14px 0 0; max-width: 72ch; font-size: 0.875rem; line-height: 1.5; color: var(--mk-ink-muted, #5c5a52); }
}

/* SVG parts */
.ground { stroke: var(--mk-ink-muted, #5c5a52); stroke-width: 1; stroke-dasharray: 2 5; fill: none; vector-effect: non-scaling-stroke; }
.rim { fill: none; stroke: var(--hc-metal); }
.spokes { fill: none; stroke: var(--hc-spoke); stroke-width: 0.8; vector-effect: non-scaling-stroke; }
.hub { fill: var(--hc-metal); stroke: var(--hc-line); stroke-width: 1; vector-effect: non-scaling-stroke; }
.tyre { fill: none; stroke: var(--hc-rubber); }
.tan { fill: none; stroke: var(--hc-tan); }
.knobs { fill: none; stroke: var(--hc-rubber); }
.edge { fill: none; stroke: var(--hc-line); stroke-width: 1.1; vector-effect: non-scaling-stroke; }
.outline { fill: none; stroke: var(--hc-line); stroke-linecap: round; stroke-linejoin: round; }
.outlineFill { fill: var(--hc-line); }
.paint { fill: none; stroke-linecap: round; stroke-linejoin: round; }
.paintFill { stroke: none; }
.tiShine { fill: none; stroke: var(--hc-ti-hi); stroke-linecap: round; }
.badge { fill: var(--hc-brass); stroke: var(--hc-line); stroke-width: 1; vector-effect: non-scaling-stroke; }
.decal {
  font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 30px; font-weight: 700; letter-spacing: 0.32em;
  text-anchor: middle; dominant-baseline: central; fill: #f6f3ea;
}
.decal[data-light='true'] { fill: #1d1d1a; }
.alloy { fill: none; stroke: var(--hc-metal); stroke-linecap: round; stroke-linejoin: round; }
.metalOutlined { fill: none; stroke: var(--hc-metal); stroke-linecap: round; paint-order: stroke; }
.rubber { fill: none; stroke: var(--hc-rubber); stroke-linecap: round; }
.stay { fill: none; stroke: var(--hc-metal); stroke-width: 1.4; vector-effect: non-scaling-stroke; }
.rack { fill: none; stroke: var(--hc-rubber); stroke-linecap: round; stroke-linejoin: round; }
.chain { fill: none; stroke: var(--hc-spoke); stroke-linecap: round; }
.mech { fill: none; stroke: var(--hc-rubber); stroke-linecap: round; }
.jockey { fill: var(--hc-rubber); stroke: var(--hc-metal); stroke-width: 1; vector-effect: non-scaling-stroke; }
.cog { fill: none; stroke: var(--hc-metal); }
.ring { fill: none; stroke: var(--hc-metal); }
.crank { fill: none; stroke: var(--hc-metal); stroke-linecap: round; }
.saddle { fill: var(--hc-rubber); stroke: var(--hc-line); stroke-width: 1; vector-effect: non-scaling-stroke; }
.stem { fill: none; stroke: var(--hc-metal); stroke-linecap: round; }
.tape { fill: none; stroke: var(--hc-rubber); stroke-linecap: round; stroke-linejoin: round; }
.wire { fill: none; stroke: var(--hc-rubber); stroke-width: 1.4; vector-effect: non-scaling-stroke; }
.lamp { fill: var(--hc-rubber); stroke: var(--hc-line); stroke-width: 1; vector-effect: non-scaling-stroke; }
.lens { fill: var(--hc-lens); stroke: var(--hc-line); stroke-width: 1; vector-effect: non-scaling-stroke; }
.tail { fill: var(--hc-tail); stroke: var(--hc-line); stroke-width: 1; vector-effect: non-scaling-stroke; }
.dimLines { pointer-events: none; }
.dim { fill: none; stroke: var(--mk-signal, #bf2f09); stroke-width: 1; vector-effect: non-scaling-stroke; }
.ext { fill: none; stroke: var(--mk-signal, #bf2f09); stroke-width: 1; stroke-dasharray: 3 4; vector-effect: non-scaling-stroke; }

/* Cross-fades: every variant is drawn, the chosen one is opaque. */
.part { opacity: 0; }
.part[data-on='true'] { opacity: 1; }
.lift { transform: translateY(-14px); }
.lift[data-on='true'] { transform: none; }
@media (prefers-reduced-motion: no-preference) {
  .root:not([data-reduced]) .part { transition: opacity var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease), transform var(--mk-duration-moderate, 360ms) var(--mk-ease-emphasized, ease); }
  .root:not([data-reduced]) .paint { transition: stroke var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease); }
  .root:not([data-reduced]) .paintFill { transition: fill var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease); }
}

/* HTML dimension labels laid over the drawing */
.dims { position: absolute; inset: 0; pointer-events: none; }
.dimLabel {
  position: absolute;
  transform: translate(0, -50%);
  padding: 1px 4px;
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.75rem;
  line-height: 1.2;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  white-space: nowrap;
  color: var(--mk-signal, #bf2f09);
  background: var(--mk-surface, #fbf9f4);
  font-variant-numeric: tabular-nums;
}
.dimLabel[data-align='center'] { transform: translate(-50%, -50%); }
.dimLabel b { font-weight: 700; }

/* Total strip under the drawing */
.strip { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding-top: 10px; }
.total { display: flex; align-items: baseline; gap: 10px; margin: 0; }
.totalLabel { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); }
.totalValue { font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif); font-size: 1.625rem; font-weight: 700; letter-spacing: -0.02em; }
@container (min-width: 960px) {
  .strip { padding-top: 18px; margin-top: 18px; border-top: 1px solid var(--mk-line, #11110f24); }
  .totalValue { font-size: 2.25rem; }
}

/* Odometer */
.ticker { display: inline-flex; }
.tickRow { display: inline-flex; font-variant-numeric: tabular-nums; }
.tickDigit { display: inline-block; height: 1.1em; line-height: 1.1em; overflow: hidden; }
.tickStrip { display: flex; flex-direction: column; }
.tickCell { display: block; height: 1.1em; width: 0.62em; text-align: center; }
.tickSymbol { display: inline-block; height: 1.1em; line-height: 1.1em; }

/* ── Buttons ───────────────────────────────────────────────────────────── */
.primary, .secondary {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  min-height: 48px; padding: 0 20px; border-radius: var(--mk-radius-s, 4px);
  font: 600 0.9375rem/1 var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
  cursor: pointer; transition: background-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease), transform var(--mk-duration-instant, 90ms);
}
.primary { border: 0; background: var(--mk-signal, #bf2f09); color: var(--mk-on-signal, #fff); }
.primary:hover { background: color-mix(in oklab, var(--mk-signal, #bf2f09) 86%, #000); }
.secondary { border: 1px solid var(--mk-line-strong, #11110f); background: transparent; color: var(--mk-ink, #11110f); }
.secondary:hover { background: var(--mk-surface-2, #e9e5da); }
.primary:active, .secondary:active { transform: translateY(1px) scale(0.99); }
.primary:focus-visible, .secondary:focus-visible, .textBtn:focus-visible, .compareLink:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 3px; }
.textBtn {
  min-height: 32px; padding: 4px 2px; border: 0; background: none; color: var(--mk-ink, #11110f); cursor: pointer;
  font: 500 0.875rem/1.3 var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
  text-decoration: underline; text-underline-offset: 3px; text-decoration-thickness: 1px; text-align: left;
}
.textBtn:hover { text-decoration-thickness: 2px; }

/* ── Options ───────────────────────────────────────────────────────────── */
.group { margin: 0; padding: 22px 0 26px; border: 0; border-top: 1px solid var(--mk-line, #11110f24); min-inline-size: 0; }
.legend {
  display: flex; align-items: baseline; gap: 10px; padding: 0; float: left; width: 100%;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif); font-weight: 650; font-size: 1.1875rem; letter-spacing: -0.015em;
}
.legend + * { clear: both; }
.num { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; font-weight: 400; letter-spacing: 0.04em; color: var(--mk-signal, #bf2f09); }
.hint { margin: 8px 0 0; padding-top: 4px; max-width: 52ch; font-size: 0.875rem; line-height: 1.45; color: var(--mk-ink-muted, #5c5a52); }
.choices { display: grid; gap: 8px; margin-top: 14px; grid-template-columns: repeat(auto-fill, minmax(min(100%, 9.75rem), 1fr)); }
.choices[data-kind='size'] { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.choices[data-kind='frame'] { grid-template-columns: repeat(auto-fill, minmax(min(100%, 13rem), 1fr)); }
.choices[data-kind='paint'] { grid-template-columns: repeat(2, minmax(0, 1fr)); }

.choice, .extra {
  position: relative;
  display: grid;
  align-content: start;
  gap: 3px;
  min-height: 48px;
  padding: 12px 12px 11px;
  border: 1px solid var(--mk-line, #11110f24);
  border-radius: var(--mk-radius-s, 4px);
  background: var(--mk-surface, #fbf9f4);
  cursor: pointer;
  transition: background-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease), border-color var(--mk-duration-fast, 160ms);
}
.choice:hover, .extra:hover { background: var(--mk-surface-2, #e9e5da); }
.choice:has(:checked), .extra:has(:checked) { border-color: var(--mk-ink, #11110f); box-shadow: inset 0 0 0 1px var(--mk-ink, #11110f); }
.choice:has(:focus-visible), .extra:has(:focus-visible) { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }
.input {
  position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; opacity: 0; cursor: pointer;
  scroll-margin-top: calc(44px + var(--plate-h) + 12px);
  scroll-margin-bottom: 24px;
}
@container (min-width: 960px) { .input { scroll-margin-top: 64px; } }

/* selection mark: ring when free, filled when chosen */
.choice::after {
  content: ''; position: absolute; top: 12px; right: 12px; width: 10px; height: 10px; border-radius: 50%;
  border: 1.5px solid var(--mk-ink-muted, #5c5a52);
}
.choice:has(:checked)::after { background: var(--mk-ink, #11110f); border-color: var(--mk-ink, #11110f); box-shadow: inset 0 0 0 2px var(--mk-surface, #fbf9f4); }

.name { font-weight: 600; font-size: 0.9375rem; line-height: 1.25; padding-right: 18px; }
.note { font-size: 0.8125rem; line-height: 1.35; color: var(--mk-ink-muted, #5c5a52); }
.delta { margin-top: 6px; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.75rem; letter-spacing: 0.02em; font-variant-numeric: tabular-nums; color: var(--mk-ink, #11110f); }

.sizeNum { font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif); font-weight: 700; font-size: 1.625rem; line-height: 1; letter-spacing: -0.03em; }
.choices[data-kind='size'] .choice { padding-inline: 10px; }
.choices[data-kind='size'] .note { font-size: 0.75rem; }

.paintRow { display: flex; align-items: center; gap: 10px; }
.paintText { display: grid; gap: 2px; }
.swatch { flex: none; width: 28px; height: 28px; border-radius: 50%; box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--mk-ink, #11110f) 35%, transparent); }

.barIcon { width: 76px; height: 38px; margin: -2px 0 4px -4px; overflow: visible; }
.icStem { fill: none; stroke: var(--hc-metal); stroke-linecap: round; }
.icOutline { fill: none; stroke: var(--hc-line); stroke-linecap: round; stroke-linejoin: round; }
.icTape { fill: none; stroke: var(--hc-rubber); stroke-linecap: round; stroke-linejoin: round; }
.icMetal { fill: none; stroke: var(--hc-metal); stroke-linecap: round; stroke-linejoin: round; }

.geo { display: flex; flex-wrap: wrap; margin: 16px 0 0; border: 1px solid var(--mk-line, #11110f24); border-width: 1px 1px 0 0; }
.geo > div { flex: 1 1 5.6rem; padding: 8px 10px; border: solid var(--mk-line, #11110f24); border-width: 0 0 1px 1px; }
.geo dt { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); }
.geo dd { margin: 2px 0 0; font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.9375rem; font-variant-numeric: tabular-nums; }

.notice, .blockedNote {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 12px; margin: 12px 0 0; padding: 10px 12px;
  border-left: 2px solid var(--mk-signal, #bf2f09); background: var(--mk-surface, #fbf9f4); font-size: 0.875rem; line-height: 1.4;
}
.blockedNote { margin-top: 8px; }

.extras { display: grid; gap: 8px; margin-top: 14px; }
.extraItem { display: grid; }
.extra { grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 12px; }
.extra .delta { margin: 0; }
.extraText { display: grid; gap: 2px; }
.box {
  display: grid; place-items: center; width: 22px; height: 22px; border-radius: 3px;
  border: 1.5px solid var(--mk-ink-muted, #5c5a52); background: var(--mk-surface, #fbf9f4);
}
.box svg { width: 16px; height: 16px; fill: none; stroke: var(--mk-bg, #f3f0e8); stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; opacity: 0; }
.extra:has(:checked) .box { background: var(--mk-ink, #11110f); border-color: var(--mk-ink, #11110f); }
.extra:has(:checked) .box svg { opacity: 1; }
.extra[data-blocked] { border-style: dashed; cursor: not-allowed; background: transparent; }
.extra[data-blocked] .input { cursor: not-allowed; }
.extra[data-blocked] .name { text-decoration: line-through; text-decoration-thickness: 1px; }

/* ── Ticket (summary) ──────────────────────────────────────────────────── */
.ticket {
  margin-top: 8px;
  padding: 22px 20px 20px;
  background: var(--mk-surface, #fbf9f4);
  border: 1px solid var(--mk-line, #11110f24);
  border-radius: var(--mk-radius-m, 10px);
  scroll-margin-top: calc(44px + var(--plate-h) + 12px);
}
@container (min-width: 960px) { .ticket { scroll-margin-top: 64px; } }
.ticketHead { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; padding-bottom: 14px; border-bottom: 1px dashed var(--mk-line-strong, #11110f); }
.ticketTitle { margin: 0; font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif); font-size: 1.375rem; font-weight: 700; letter-spacing: -0.02em; }
.ticketTitle:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 4px; }
.lines { margin: 0; }
.line { display: grid; grid-template-columns: minmax(6.5rem, auto) minmax(0, 1fr) auto; gap: 4px 14px; align-items: baseline; padding: 10px 0; border-bottom: 1px solid var(--mk-line, #11110f24); }
.line dt { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.6875rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--mk-ink-muted, #5c5a52); }
.line dd { margin: 0; font-size: 0.9375rem; }
.linePrice { font-family: var(--mk-font-mono, ui-monospace, monospace); font-size: 0.8125rem !important; font-variant-numeric: tabular-nums; text-align: right; }
